#include <stdio.h>

int main(void) {
    const char *s = "hello";     /* 指向只读段的字面量 */
    char buf[] = "hello";        /* 栈上可写副本 */

    printf("sizeof(s)   = %zu (指针)\n", sizeof(s));
    printf("sizeof(buf) = %zu (数组，含结尾 0)\n", sizeof(buf));

    buf[0] = 'H';                /* 合法：buf 是副本 */
    printf("修改后 buf  = %s\n", buf);
    printf("字面量仍是  = %s\n", s);
    printf("字面量不可写：char *p = \"abc\"; p[0]='X'; 会触发段错误\n");
    return 0;
}
